"""Original-center midpoint/PV amplitude operator; unweighted density samples.

The off-cut midpoint rational functions and assigned physical PV+iI values
form a discrete operator prescription. The latter are not the literal limits
of the former at their poles. No coefficient bound or later gauge inputs enter.
"""
from math import factorial


def density_labels(M):
    if type(M) is not int or M<1:raise ValueError('A positive integer node count is required')
    return ([('T0',0,0)]+[('sigma1',i,0) for i in range(M)]+[('sigma2',i,0) for i in range(M)]
        +[('rho1',i,j) for i in range(M) for j in range(M)]
        +[('rho2',i,j) for i in range(M) for j in range(i,M)])


def midpoint_grid(M):
    """Exact-source Arb nodes and w=Delta_phi*x'/pi=x'/M, center nu0=0."""
    from flint import arb
    density_labels(M);nodes=[];weights=[]
    for j in range(M):
        angle=arb(2*j+1)/(4*M);cosine=angle.cos_pi();sine=angle.sin_pi()
        x=4/(cosine*cosine);w=x*sine/(M*cosine)
        nodes.append(x);weights.append(w)
    return nodes,weights


def pv_matrix(M):
    """Integrated subtracted PV map: sin(nphi)->cos(nphi), including Nyquist."""
    from flint import arb,arb_mat
    density_labels(M);values=[]
    for m in range(2*M):
        if m%2==0:values.append(arb(0))
        else:
            angle=arb(m)/(2*M)
            values.append(angle.cos_pi()/(M*angle.sin_pi()))
    return arb_mat(M,M,[-values[(k-i)%(2*M)]+values[(k+i+1)%(2*M)]
        for k in range(M) for i in range(M)])


def exterior_legendre_q(ell,z):
    """Real integral-defined Q outside[-1,1], explicitly continued to z<-1."""
    from flint import arb
    if type(ell) is not int or ell<0:raise ValueError('Nonnegative integer spin required')
    z=arb(z)
    if z>1:sign=1
    elif z<-1:sign=(-1)**(ell+1);z=-z
    else:raise ValueError('A separated real exterior Legendre-Q argument is required')
    coefficient=arb(2**ell*factorial(ell)**2)/factorial(2*ell+1)
    argument=1/(z*z)
    hyper=argument.hypgeom_2f1(arb(ell+1)/2,arb(ell+2)/2,arb(2*ell+3)/2)
    answer=sign*coefficient*z**(-ell-1)*hyper
    if not answer.is_finite():raise ArithmeticError('Exterior Legendre-Q enclosure is unresolved')
    return answer


def angular_kernels(s,nodes,weights,ell,*,subtracted=True):
    """All angular blocks use f=(1/4)integral P_l, with no pi*beta factor."""
    from flint import arb
    s=arb(s);nodes=[arb(x) for x in nodes];weights=[arb(w) for w in weights]
    M=len(nodes)
    if M<1 or len(weights)!=M or not s>0 or any(not x>4 for x in nodes) or any(not w>0 for w in weights):
        raise ValueError('Positive s, source nodes x>4 and matching positive weights required')
    if type(ell) is not int or ell<0:raise ValueError('Nonnegative integer spin required')
    epsilon=(-1)**ell;c=arb(1)/2 if ell==0 else arb(0);d=s-4
    b=[w/x for w,x in zip(weights,nodes)]
    if s==4:A=[c*wi/xi for wi,xi in zip(weights,nodes)]
    elif s>4 or s<4:A=[wi*exterior_legendre_q(ell,1+2*xi/d)/d for wi,xi in zip(weights,nodes)]
    else:raise ValueError('An s interval crossing threshold needs a separate limit treatment')
    J=[a-c*bi for a,bi in zip(A,b)] if subtracted else list(A)
    W=[[weights[i]*(1/(nodes[i]+nodes[j]+d)-1/nodes[i]) for j in range(M)] for i in range(M)]
    W00=[[b[i]*b[j] for j in range(M)] for i in range(M)]
    U=[[arb(0) for _ in range(M)] for _ in range(M)]
    for i in range(M):
        for j in range(i,M):
            if ell%2 and i==j:value=arb(0)
            elif s==4 and subtracted:value=arb(0)
            elif subtracted:value=A[i]*W[j][i]+epsilon*A[j]*W[i][j]+c*W00[i][j]
            else:value=(weights[j]*A[i]+epsilon*weights[i]*A[j])/(nodes[i]+nodes[j]+d)
            U[i][j]=value;U[j][i]=epsilon*value
    if s==4 and subtracted:J=[arb(0) for _ in range(M)]
    return dict(s=s,nodes=nodes,weights=weights,ell=ell,epsilon=epsilon,c=c,A=A,J=J,U=U,b=b,W=W,W00=W00,
        subtracted=subtracted,normalization='f=(1/4)integral P_l T; w=xprime/M includes1/pi')


def assemble_density_row(direct,blocks,isospin):
    """rho2 upper entries are actual symmetric density values, not half-basis coefficients."""
    M=len(direct);ell=blocks['ell'];epsilon=blocks['epsilon'];c=blocks['c'];J=blocks['J'];U=blocks['U']
    if isospin not in (0,1,2):raise ValueError('Isospin must be0,1,2')
    if len(J)!=M or len(U)!=M or any(len(row)!=M for row in U):raise ValueError('Angular and direct blocks disagree')
    zero=direct[0]*0
    if ell%2!=int(isospin==1):return [zero for _ in density_labels(M)]
    def combine(a,b):
        return 3*a+(1+epsilon)*b if isospin==0 else (1-epsilon)*b if isospin==1 else (1+epsilon)*b
    row=[combine(c,c)]
    row.extend(combine(c*direct[i],J[i]) for i in range(M))
    row.extend(combine((1+epsilon)*J[i],c*direct[i]+epsilon*J[i]) for i in range(M))
    row.extend(combine((1+epsilon)*direct[i]*J[j],direct[j]*J[i]+U[i][j]) for i in range(M) for j in range(M))
    for i in range(M):
        for j in range(i,M):
            a=U[i][i] if i==j else (1+epsilon)*U[i][j]
            b=epsilon*direct[i]*J[i] if i==j else epsilon*(direct[i]*J[j]+direct[j]*J[i])
            row.append(combine(a,b))
    return [zero+value for value in row]


def offcut_row(s,nodes,weights,ell,isospin,*,subtracted=True):
    """Real subthreshold row, including the source's five0<s<4 evaluation energies."""
    from flint import arb
    s=arb(s)
    if not 0<s<4:raise ValueError('This off-cut API is restricted to0<s<4')
    blocks=angular_kernels(s,nodes,weights,ell,subtracted=subtracted)
    direct=[w*(1/(x-s)-(1/x if subtracted else 0)) for x,w in zip(blocks['nodes'],blocks['weights'])]
    return assemble_density_row(direct,blocks,isospin)


def physical_node_row(node,nodes,weights,pv,ell,isospin,*,subtracted=True):
    """Assigned physical PV+jump row; never evaluates a rational function at its pole."""
    from flint import acb
    M=len(nodes)
    if type(node) is not int or not 0<=node<M or pv.nrows()!=M or pv.ncols()!=M:
        raise ValueError('Matching node and full M-square PV matrix required')
    blocks=angular_kernels(nodes[node],nodes,weights,ell,subtracted=subtracted)
    direct=[acb(pv[node,i]+(0 if subtracted else blocks['b'][i]),int(node==i)) for i in range(M)]
    return assemble_density_row(direct,blocks,isospin)
